const { app, BrowserWindow, Menu } = require('electron');
const path = require('path');
const { spawn } = require('child_process');
const net = require('net');

let backendProcess, frontendProcess, mainWindow, splashWindow;

const isDev = !app.isPackaged;
const resourcesPath = isDev ? path.join(__dirname, '..') : process.resourcesPath;
const NODE_EXE = isDev ? 'node' : path.join(resourcesPath, 'tools', 'node.exe');

const BACKEND_PORT = 4000;
const FRONTEND_PORT = 3000;

function startBackend() {
  const serverPath = path.join(resourcesPath, 'backend', 'server.js');
  backendProcess = spawn(NODE_EXE, [serverPath], {
    cwd: path.join(resourcesPath, 'backend'),
    env: { ...process.env, PORT: BACKEND_PORT },
  });
  backendProcess.stdout.on('data', (d) => console.log(`[backend] ${d}`));
  backendProcess.stderr.on('data', (d) => console.error(`[backend] ${d}`));
}

function startFrontend() {
  const serverPath = path.join(resourcesPath, 'frontend', '.next', 'standalone', 'server.js');
  frontendProcess = spawn(NODE_EXE, [serverPath], {
    cwd: path.join(resourcesPath, 'frontend', '.next', 'standalone'),
    env: { ...process.env, PORT: FRONTEND_PORT },
  });
  frontendProcess.stdout.on('data', (d) => console.log(`[frontend] ${d}`));
  frontendProcess.stderr.on('data', (d) => console.error(`[frontend] ${d}`));
}

// Create splash screen
function createSplashScreen() {
    splashWindow = new BrowserWindow({
      width: 500,
      height: 345,
      frame: true,
      transparent: false,
      alwaysOnTop: false,
      resizable: false,
      autoHideMenuBar: true,
      webPreferences: {
        nodeIntegration: false,
        contextIsolation: true
      }
    });
  
    const splashHTML = `
    <!DOCTYPE html>
    <html>
    <head>
      <meta charset="UTF-8" />
      <title>ZeeroX POS</title>
      <style>
        * { margin: 0; padding: 0; box-sizing: border-box; }
        body {
          font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Arial, sans-serif;
          background: linear-gradient(180deg, #f0f4f8 0%, #eef2f5 100%);
          display: flex;
          justify-content: center;
          align-items: center;
        }
        .splash-wrapper { width: 500px; height: 305px; background: #ffffff; }
        .splash-header {
          background: linear-gradient(90deg, #06395f, #0b4f7a);
          padding: 16px 20px;
          display: flex;
          flex-direction: column;
          align-items: center;
          gap: 5px;
        }
        .splash-header img { width: 50px; height: auto; }
        .header-text { color: #ffffff; }
        .header-text .title { font-size: 16px; font-weight: 600; }
        .splash-body { padding: 36px 40px 32px; text-align: center; }
        .app-name { font-size: 20px; font-weight: 600; color: #0b3c5d; margin-bottom: 6px; }
        .tagline { font-size: 12px; color: #6c757d; margin-bottom: 28px; }
        .progress { height: 3px; background: #e6ebf0; overflow: hidden; margin-bottom: 12px; }
        .bar {
          height: 100%;
          width: 0%;
          background: #0b5ed7;
          animation: load 1.6s ease-in-out infinite;
        }
        @keyframes load {
          0% { width: 0%; }
          40% { width: 65%; }
          70% { width: 85%; }
          100% { width: 100%; }
        }
        .status { font-size: 12px; color: #495057; letter-spacing: 0.3px; }
        footer { color: #6c757d; text-align: center; font-size: 12px; margin-bottom: 5px; }
      </style>
    </head>
    <body>
      <div class="splash-wrapper">
        <div class="splash-header">
          <img src="data:image/png;base64," alt="ZeeroX POS">
          <div class="header-text">
            <div class="title">ZeeroX - POS System</div>
          </div>
        </div>
        <div class="splash-body">
          <div class="app-name">Starting Application</div>
          <div class="tagline">Please wait while services are loading</div>
          <div class="progress">
            <div class="bar"></div>
          </div>
          <div class="status">Initializing services…</div>
        </div>
        <footer><small>Powered by ZeeroX</small></footer>
      </div>
    </body>
    </html>
    `;
    
    splashWindow.loadURL(`data:text/html;charset=utf-8,${encodeURIComponent(splashHTML)}`);
  }


function waitForPort(port, cb) {
  const tryConnect = () => {
    const socket = net.createConnection(port, '127.0.0.1');
    socket.on('connect', () => { socket.end(); cb(); });
    socket.on('error', () => setTimeout(tryConnect, 500));
  };
  tryConnect();
}

function createWindow() {
  mainWindow = new BrowserWindow({
    width: 1280,
    height: 800,
    icon: path.join(__dirname, 'assets', 'icon.ico'),
    webPreferences: {
      zoomFactor: 0.9,
    },
  });
  mainWindow.loadURL(`http://localhost:${FRONTEND_PORT}`);
}

// Same look as the main window (icon, zoom); shares the session so the user stays logged in
function openInNewWindow(url) {
  const win = new BrowserWindow({
    width: 1280,
    height: 800,
    icon: path.join(__dirname, 'assets', 'icon.ico'),
    webPreferences: {
      zoomFactor: 0.9,
    },
  });
  win.loadURL(url);
}

// Right-click on any in-app link (sidebar pages etc.) -> "Open in New Tab"
// Registered for every window, so it also works inside windows opened this way
// and inside "Another Sale" windows.
app.on('web-contents-created', (_event, contents) => {
  contents.on('context-menu', (_e, params) => {
    const url = params.linkURL;
    if (!url || !url.startsWith(`http://localhost:${FRONTEND_PORT}`)) return; // skip tel: links, empty space, etc.

    Menu.buildFromTemplate([
      { label: 'Open in New Tab', click: () => openInNewWindow(url) },
    ]).popup({ window: BrowserWindow.fromWebContents(contents) });
  });
});


app.whenReady().then(() => {
    const menuTemplate = [
      {
        label: 'File',
        submenu: [{ role: 'quit' }]
      },
      {
        label: 'Edit',
        submenu: [
          { role: 'undo' },
          { role: 'redo' },
          { type: 'separator' },
          { role: 'cut' },
          { role: 'copy' },
          { role: 'paste' },
        ]
      },
      {
        label: 'View',
        submenu: [
          { role: 'reload' },
          { role: 'resetZoom' },
          { role: 'zoomIn' },
          { role: 'zoomOut' },
          { type: 'separator' },
          { role: 'togglefullscreen' },
        ]
      },
      {
        label: 'Window',
        submenu: [
          { role: 'minimize' },
          { role: 'close' },
        ]
      }
    ];
    Menu.setApplicationMenu(Menu.buildFromTemplate(menuTemplate));
    createSplashScreen();
    startBackend();
    startFrontend();
    let readyCount = 0;
function onPortReady() {
  readyCount++;
  if (readyCount === 2) {
    createWindow();
    if (splashWindow) { splashWindow.close(); splashWindow = null; }
  }
}
waitForPort(BACKEND_PORT, onPortReady);
waitForPort(FRONTEND_PORT, onPortReady);
  });

app.on('window-all-closed', () => {
  if (backendProcess) backendProcess.kill();
  if (frontendProcess) frontendProcess.kill();
  if (process.platform !== 'darwin') app.quit();
});